inputs = ['aevvx', 'ihhevi', 'fkjuvk', 'jx', 'edewb']
outputs = ['haax', 'ihhekai', 'fkjuak', 'jx', 'ekdekwb']

# Find changed pairs manually
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Analyze what needs to change in each case
print("\nDetailed analysis:")
for idx, inp, outp in changed_pairs:
    print(f"Index {idx}: '{inp}' -> '{outp}'")
    # Find positions where characters differ
    for i, (char_in, char_out) in enumerate(zip(inp, outp)):
        if char_in != char_out:
            print(f"  Position {i}: '{char_in}' -> '{char_out}'")
    # Handle cases where lengths differ
    if len(inp) != len(outp):
        if len(inp) > len(outp):
            print(f"  Length decreased from {len(inp)} to {len(outp)}")
        else:
            print(f"  Length increased from {len(inp)} to {len(outp)}")

